// ------------------------------------
// PHOTO SLIDESHOW
// ------------------------------------

const photoFiles = Array.from(
  { length: 11 },
  (_, index) => `photo-${String(index + 1).padStart(2, "0")}.jpeg`
);

const heroPhoto = document.getElementById("hero-photo");
const galleryPhoto = document.getElementById("gallery-photo");
const photoCurrent = document.getElementById("photo-current");
const galleryNumber = document.getElementById("gallery-number");

let activePhoto = 0;
let slideshowTimer;

function setPhoto(index) {
  activePhoto = (index + photoFiles.length) % photoFiles.length;

  const src = `images/${photoFiles[activePhoto]}`;

  [heroPhoto, galleryPhoto].forEach((img) => {
    if (!img) return;

    const preloader = new Image();

    preloader.onload = () => {
      img.src = src;
    };

    preloader.src = src;
  });

  const number = String(activePhoto + 1).padStart(2, "0");

  if (photoCurrent) photoCurrent.textContent = number;

  if (galleryNumber) {
    galleryNumber.textContent =
      `${number} / ${String(photoFiles.length).padStart(2, "0")}`;
  }
}

function startSlideshow() {
  clearInterval(slideshowTimer);

  slideshowTimer = setInterval(() => {
    setPhoto(activePhoto + 1);
  }, 5500);
}

document.getElementById("previous-photo")?.addEventListener("click", () => {
  setPhoto(activePhoto - 1);
  startSlideshow();
});

document.getElementById("next-photo")?.addEventListener("click", () => {
  setPhoto(activePhoto + 1);
  startSlideshow();
});

setPhoto(0);
startSlideshow();

// ------------------------------------
// PASSWORD VISIBILITY
// ------------------------------------

document.getElementById("toggle-password")?.addEventListener("click", () => {
  const passwordInput = document.getElementById("password");
  const toggleButton = document.getElementById("toggle-password");

  const visible = passwordInput.type === "password";

  passwordInput.type = visible ? "text" : "password";
  toggleButton.textContent = visible ? "Hide" : "Show";
});

// ------------------------------------
// PERSONAL LETTER LOGIN
// ------------------------------------

const loginForm = document.getElementById("login-form");
const loginStatus = document.getElementById("login-status");
const letterPanel = document.getElementById("letter-panel");

function showLetter(person) {
  document.getElementById("letter-recipient").textContent =
    person.recipientName;

  document.getElementById("letter-title").textContent =
    person.title;

  document.getElementById("letter-message").textContent =
    person.message;

  document.getElementById("letter-signature").textContent =
    person.signature;

  // Hide the password form.
  loginForm.hidden = true;

  // Display the private letter.
  letterPanel.hidden = false;

  loginStatus.textContent = "";

  // Scroll to the actual private letter.
  setTimeout(() => {
    letterPanel.scrollIntoView({
      behavior: "smooth",
      block: "center"
    });
  }, 100);
}

// Handle password submission.
loginForm?.addEventListener("submit", function (event) {
  event.preventDefault();
  event.stopPropagation();

  const enteredPassword =
    document.getElementById("password").value.trim();

  const person = personalLetters.find(
    (item) => item.password === enteredPassword
  );

  if (person) {
    showLetter(person);
  } else {
    loginStatus.textContent =
      "Incorrect password. Please check your password and try again.";
  }
});

// Sign out and return to the password form.
document.getElementById("sign-out")?.addEventListener("click", function () {
  letterPanel.hidden = true;
  loginForm.hidden = false;
  loginForm.reset();
  loginStatus.textContent = "";
});